using System.Text.Json;
using NIsland.Core;
using NIsland.Services;
int checks=0;void Check(bool ok,string why){checks++;if(!ok)throw new Exception(why);}
var now=DateTime.UtcNow;string file=Path.Combine(Store.Dir,"index.json");var ledger=new ReplyLedger(file);
ReplyLedger.Entry E(long chat,long id,double hours=0)=>new(chat,id,now.AddHours(-hours));
Check(ledger.Replace("a",new[]{E(42,1),E(42,2)},Array.Empty<long>(),now).Length==0,"initial deletion");
Check(ledger.Replace("a",Array.Empty<ReplyLedger.Entry>(),Array.Empty<long>(),now).Length==0,"failed send deleted old");
var old=ledger.Replace("a",new[]{E(42,3)},Array.Empty<long>(),now);Check(old.Length==2&&old.All(e=>e.Chat==42),"multipart replacement");
Check(new ReplyLedger(file).Replace("a",new[]{E(42,4)},Array.Empty<long>(),now).Single().Id==3,"persistence");
ledger.Replace("age",new[]{E(42,5,48)},Array.Empty<long>(),now);Check(ledger.Replace("age",new[]{E(42,6)},Array.Empty<long>(),now).Length==0,"too old removed");
ledger.Replace("keep",new[]{E(42,7)},Array.Empty<long>(),now);Check(ledger.Replace("keep",Array.Empty<ReplyLedger.Entry>(),new[]{7L},now).Length==0,"edited message deleted");
Check(ledger.Replace("other",new[]{E(43,1)},Array.Empty<long>(),now).Length==0,"cross key deletion");
string Msg(string text,long id=42)=>JsonSerializer.Serialize(new{message=new{chat=new{id,type="private"},from=new{id},text}});
var hub=new TelegramHub();await hub.Update(Msg("/menu multi"));Check(hub.Sent.Count(s=>s.Method=="deleteMessage")==0,"first request");
hub.Sent.Clear();await hub.Update(Msg("/menu"));Check(hub.Sent.Count(s=>s.Method=="deleteMessage")==2,"actual wrapper multipart deletion");
hub.Sent.Clear();try{await hub.Update(Msg("/menu fail"));}catch(InvalidOperationException){}Check(hub.Sent.Count==0,"failed handler deleted replies");
var restarted=new TelegramHub();await restarted.Update(Msg("/menu"));Check(restarted.Sent.Count(s=>s.Method=="deleteMessage")==1,"wrapper restart persistence");
restarted.Sent.Clear();await restarted.Update(Msg("/help"));Check(restarted.Sent.All(s=>s.Method!="deleteMessage"),"unrelated reply deleted");
restarted.Sent.Clear();await restarted.Update(Msg("/menu",999));Check(restarted.Sent.Count==0,"foreign chat touched");
restarted.Sent.Clear();await Task.WhenAll(restarted.Update(Msg("/menu slow")),restarted.Update(Msg("/menu")));
var sends=restarted.Sent.Where(s=>s.Method=="sendMessage").ToArray();var deleted=restarted.Sent.Where(s=>s.Method=="deleteMessage").Select(s=>s.Body.GetProperty("message_id").GetInt64()).ToArray();
Check(sends.Length==2&&deleted.Contains(sends[0].Body.ValueKind==JsonValueKind.Object?0:-1)==false,"concurrent sends missing");
Check(deleted.Length==2,"same-purpose requests not serialized");
Check(!File.ReadAllText(file).Contains("test-token"),"token persisted");Check(Log.Errors.Count==0,"cleanup exception");
var formatted=MenuRichRenderer.Render("🎛 <b>Menu</b>\nIntro\n\n<b>Section</b>\nText\n\n• One\n• Two");
Check(formatted.Contains("<h3>")&&formatted.Contains("<h4>Section</h4>")&&formatted.Contains("<ul><li>One</li><li>Two</li></ul>"),"semantic headings/list");
var table=MenuRichRenderer.Render("\u0002"+JsonSerializer.Serialize(new[]{new[]{"Name","Value"},new[]{"<user>","42"}})+"\u0003");Check(table.Contains("<table")&&table.Contains("&lt;user&gt;")&&!table.Contains("<user>"),"table escaping");
Check(MenuRichRenderer.Render("<pre>&lt;tag&gt;\n  code</pre>").Contains("\n  code"),"pre whitespace changed");
Check(!MenuRichRenderer.Render("<b>User &lt;content&gt;</b>").Contains("<content>"),"escaped text changed");
Console.WriteLine($"PASS {checks} reply lifecycle checks; actual wrapper, restart, multipart, failure, chat boundary, concurrency; no Telegram calls.");Directory.Delete(Store.Dir,true);
